    },
    ["Cenarion Hold"] = { type = "town", faction = "neutral", home = {  },
      { "Cenarion Hold was a fortified camp in the Silithus sand, where the Cenarion Circle stood guard against the hives." },
    },
    ["Chillwind Camp"] = { type = "town", faction = "alliance", home = {  },
      { "Chillwind Camp was a handful of tents under the trees at the edge of the Plaguelands, where the Alliance kept a foothold against the Scourge.", tags = { "!foe" } },
      { "Chillwind Camp was an Alliance camp on the edge of the plague, and its soldiers had as little love for me as for the Scourge.", tags = { "foe" } },
    },
    ["Darkshire"] = { type = "town", faction = "alliance", home = {  },
      { "Darkshire huddled under its lamps at the edge of the dark wood, with the Night Watch on every corner. People spoke in low voices, as if the forest might hear.", tags = { "!foe" } },
      { "Darkshire was lit and guarded against the dark, and against my kind as well. Its lamps left very few shadows.", tags = { "foe" } },
    },
    ["Darkshore"] = { type = "zone", faction = "alliance", home = {  },
      { "Mist rolled in off the sea along Darkshore, and old stones lay half buried in the grey sand. Even the trees looked tired, and I caught myself searching the shore for a light.", tags = { "!night" } },
      { "On Darkshore at night, the mist made sea and sky one grey thing. I kept my bearings by the sound of the surf and the blurred moon above it.", tags = { "night" } },
    },
    ["Darnassus"] = { type = "zone", faction = "alliance", home = { ["NightElf"] = true },
      { "The white stone and still pools of Darnassus slowed me without my meaning to. Near the Temple of the Moon the old hush settled around me, and I was home.", tags = { "home" } },
      { "I lowered my voice in Darnassus without anyone asking me to. The pale stone and quiet water seemed a long way from the pace of the road below.", tags = { "ally" } },
      { "In Darnassus, pale stone held still water. I might have admired the quiet, if it had not made every one of my footsteps sound too loud.", tags = { "foe" } },
    },
    ["Deadwind Pass"] = { type = "zone", faction = "neutral", home = {  },
      { "Deadwind Pass was dead in every sense, grey trees on grey rock, with the tower of Karazhan standing alone in the gloom. Nobody I had met could say what still lived inside it." },
      { "Deadwind Pass was colder than it had any right to be at night. Karazhan's tower rose black over the ravine, and the wind through the dead trees sounded almost like voices.", tags = { "night" } },
    },
    ["Desolace"] = { type = "zone", faction = "neutral", home = {  },
      { "Desolace was grey from edge to edge: cracked earth, old bones and the camps of warring centaur. Something had drained the life from this land, and it had never come back.", tags = { "!night" } },
      { "Night in Desolace was cold, empty and very still. The centaur drums carried a long way, and so did the howling.", tags = { "night" } },
    },
    ["Dire Maul"] = { type = "dungeon", faction = "neutral", home = {  },
      { "Dire Maul was the ruin of an elven city in the forest, its great halls overgrown, its old masters still haunting them and ogres living in the wreck." },
    },
    ["Dolanaar"] = { type = "town", faction = "alliance", home = { ["NightElf"] = true },
      { "Rain scented the houses around the moonwell in Dolanaar. The sentinels kept their patient watch on the road, and I let my guard down a little.", tags = { "home" } },
      { "The blue moonwell at Dolanaar caught my eye before the houses did. Under the trailing vines I found myself speaking softly, as if someone had asked me to.", tags = { "!home" } },
    },
    ["Dun Morogh"] = { type = "zone", faction = "alliance", home = { ["Dwarf"] = true, ["Gnome"] = true },
      { "The cold of Dun Morogh caught in my throat, and the pines bowed under their snow. Above the valleys rose the mountain that holds Ironforge, and the sight of it made the cold easier to bear.", tags = { "home", "!night" } },
      { "The snow of Dun Morogh glowed blue under the stars, and the lamps in the village windows looked warmer for it. I knew the shapes of those mountains even in the dark.", tags = { "home", "night" } },
      { "The cold of Dun Morogh found my fingers before anything else did. Ahead, the gate of Ironforge sank into the mountain, as though the dwarves had talked the stone into making room.", tags = { "ally" } },
      { "Snow lay deep across Dun Morogh, and the mountain of Ironforge stood ahead. I wondered how many dwarves were waiting behind all that stone.", tags = { "foe" } },
    },
    ["Durotar"] = { type = "zone", faction = "horde", home = { ["Orc"] = true, ["Troll"] = true },
      { "Heat rose from the red dust of Durotar, as if the ground itself were breathing. This was the land we had claimed, and I meant to learn how to belong to it.", tags = { "home", "!night" } },
      { "The red earth of Durotar faded to grey as the heat left the stones. From beyond the hills came the drums of Orgrimmar, a sound I could have followed blind.", tags = { "home", "night" } },
      { "In Durotar the red hills closed around the road to Orgrimmar. Under that sun, I began to understand the people who had chosen to stay.", tags = { "ally" } },
      { "A hot wind drove the red dust of Durotar against my face. This was the Horde's own country, and I stopped trusting the ridges to be empty.", tags = { "foe" } },
    },
    ["Duskwood"] = { type = "zone", faction = "alliance", home = {  },
      { "Duskwood was dark even at midday, the trees grown so thick that the sun barely reached the road. Things moved in the graveyards, and the people of Darkshire had stopped pretending not to notice.", tags = { "!night" } },
      { "Night in Duskwood was a darker kind of night. Worgs howled out among the trees, and at Raven Hill the dead did not stay where they had been buried.", tags = { "night" } },
    },
    ["Dustwallow Marsh"] = { type = "zone", faction = "neutral", home = {  },
      { "Dustwallow Marsh was hot, wet and humming with insects, its mud full of crocolisks and its trees heavy with moss. Theramore's towers on the coast looked very far from the swamp.", tags = { "!night" } },
      { "At night Dustwallow came alive with croaks and splashes, and mist rose off the water in sheets. Somewhere to the south was Onyxia's lair, and I could not put it out of my mind.", tags = { "night" } },
    },
    ["Eastern Plaguelands"] = { type = "zone", faction = "neutral", home = {  },
      { "The Eastern Plaguelands were a land without colour, the trees grey, the rivers foul and the ground soft with plague. Stratholme's walls stood to the north, and nothing living went there willingly.", tags = { "!night" } },
      { "The Eastern Plaguelands were darker than any night should be. Things walked among the dead trees, and the only kind light came from the chapel at Light's Hope, small against the dark.", tags = { "night" } },
    },
    ["Elwynn Forest"] = { type = "zone", faction = "alliance", home = { ["Human"] = true },
      { "Elwynn's woods were green and orderly, with farms tucked between the oaks and Stormwind's guards riding the roads. In country like that, it was easy to forget how close the trouble had come.", tags = { "home", "!night" } },
      { "Elwynn was quiet at night, with lanterns along the road and the trees dark on either side. Somewhere in the woods a wolf called, and the next lamp post was a welcome sight.", tags = { "home", "night" } },
      { "Elwynn Forest was gentle country, all oak and meadow and well-kept fields, with the walls of Stormwind never far away. It looked like a place people had fought hard to keep ordinary.", tags = { "ally" } },
      { "Elwynn's forest ran right up to the walls of Stormwind, and every road had a patrol on it. It was pretty country, and the heart of the Alliance; I felt every one of those patrols.", tags = { "foe" } },
    },
    ["Everlook"] = { type = "town", faction = "neutral", home = {  },
      { "Everlook was a goblin town in the snow, its walls warm with lamps and its streets full of traders who had come a long way." },
    },
    ["Feathermoon Stronghold"] = { type = "town", faction = "alliance", home = {  },
      { "Feathermoon Stronghold rose from its island off the Feralas coast, a night elf fortress reached by boat or on hippogryph back.", tags = { "!foe" } },
      { "Feathermoon Stronghold stood on its island, and its sentinels did not care for visitors of my kind.", tags = { "foe" } },
    },
    ["Felwood"] = { type = "zone", faction = "neutral", home = {  },
      { "Felwood had been forest once, and in places it still was, but the trees were twisted and the water glowed green. The demons' corruption was in everything, even the air.", tags = { "!night" } },
      { "Felwood was worse at night, when the green glow of the tainted pools was the only light. The trees creaked as if they were in pain.", tags = { "night" } },
    },
    ["Feralas"] = { type = "zone", faction = "neutral", home = {  },
      { "Feralas was green and towering, with trees as tall as any in Ashenvale and the ruins of the old elves sunk among the ferns. Rain came often, and the air smelled of growth.", tags = { "!night" } },
      { "Feralas at night was deep and dripping, the canopy so thick the stars were lost. Somewhere in the dark were the walls of Dire Maul, and nearer, the calls of animals I could not name.", tags = { "night" } },
    },
    ["Freewind Post"] = { type = "town", faction = "horde", home = {  },
      { "Freewind Post sat on top of a stone needle, reached by a creaking lift, with the whole canyon spread out below.", tags = { "!foe" } },
      { "Freewind Post stood on top of a stone needle, reached only by its lift, and its guards had seen my kind before.", tags = { "foe" } },
    },
    ["Gadgetzan"] = { type = "town", faction = "neutral", home = {  },
      { "Gadgetzan was a goblin town in the middle of the desert, walled and noisy, with a bruiser on every corner keeping a very particular kind of peace." },
    },
    ["Gnomeregan"] = { type = "dungeon", faction = "alliance", home = { ["Gnome"] = true },
      { "I had pictured the halls of Gnomeregan so many times. Among the troggs and the poisoned glow, I still caught myself searching for faces I knew.", tags = { "home" } },
      { "The machines of Gnomeregan were still turning in halls their makers had lost. Under the sickly green light, I wondered who would ever stop the wheels.", tags = { "!home" } },
    },
    ["Goldshire"] = { type = "town", faction = "alliance", home = {  },
      { "Goldshire gathered around the Lion's Pride Inn, with the forge glowing at the smithy and children running in the street. It felt like the safest place in the world.", tags = { "!foe" } },
      { "Goldshire was a cosy little Alliance town around its inn, with guards at every corner, and not one of them would have been glad to see me.", tags = { "foe" } },
    },
    ["Grom'gol Base Camp"] = { type = "town", faction = "horde", home = {  },
      { "Grom'gol was a Horde camp hacked out of the jungle, with a zeppelin tower rising over the trees and the jungle pressing in on every side.", tags = { "!foe" } },
      { "Grom'gol was a Horde camp in the jungle, its zeppelin tower visible from far off, and every grunt in it an enemy of mine.", tags = { "foe" } },
    },
    ["Hammerfall"] = { type = "town", faction = "horde", home = {  },
      { "Hammerfall stood stern and red-bannered among the Arathi hills, an orc stronghold in country the humans still called their own.", tags = { "!foe" } },
      { "Hammerfall was an orc stronghold in the Arathi hills, all spiked walls and watchful eyes, and here I was the enemy.", tags = { "foe" } },
    },
    ["Hillsbrad Foothills"] = { type = "zone", faction = "neutral", home = {  },
      { "Hillsbrad's hills were green and its orchards heavy, but Southshore and Tarren Mill sat on either side of them, and both knew it. The old farms had become a front line.", tags = { "!night" } },
      { "The foothills of Hillsbrad were uneasy at night, with the watch fires of both sides burning across the valley. Whatever peace there was here was only a pause.", tags = { "night" } },
    },
    ["Ironclad Cove"] = { type = "town", faction = "neutral", home = {  },
      { "The tunnel opened onto a hidden cove, and in the water lay a full-sized ship, armoured and lined with cannons, built in secret beneath Westfall. I understood then how much VanCleef had been planning." },
      { "Sea air reached me before I saw the cove. A great ironclad ship sat in the hidden harbour, its decks crowded with pirates, and I could hardly believe it had been built underground." },
    },
    ["Ironforge"] = { type = "zone", faction = "alliance", home = { ["Dwarf"] = true },
      { "The heat of the Great Forge met me at the gate, and the hammering followed me in. I stood above the molten iron and let the noise of my people fill the space the road had left.", tags = { "home" } },
      { "After the mountain cold, the warmth of Ironforge was almost too much. The hammers rang through every hall, and I found the sound oddly comforting after the open country.", tags = { "ally" } },
      { "The mountain closed around me in Ironforge, with hammering from every hall. There were guards everywhere, and the warmth did little to put me at ease.", tags = { "foe" } },
    },
    ["Kargath"] = { type = "town", faction = "horde", home = {  },
      { "Kargath was cut into the canyon walls of the Badlands, a hard Horde outpost named for a hard warrior.", tags = { "!foe" } },
      { "Kargath was a Horde outpost cut into the canyon walls, all watchtowers, and every one of them looked my way.", tags = { "foe" } },
    },
    ["Kharanos"] = { type = "town", faction = "alliance", home = { ["Dwarf"] = true, ["Gnome"] = true },
      { "I smelled the Thunderbrew Distillery before I had properly reached Kharanos. Smoke rose above the houses, where dwarves and gnomes crowded together against the cold, and I felt my shoulders ease at the sight.", tags = { "home" } },
      { "The smell of brewing reached me on the road into Kharanos. Among the sturdy houses I saw gnomes as well as dwarves, and thought of how far a lost home could follow its people.", tags = { "ally" } },
      { "Smoke hung over Kharanos, and the smell of ale carried well beyond the houses. It might have promised a welcome to someone else; I found myself counting the dwarves instead.", tags = { "foe" } },
    },
    ["Lakeshire"] = { type = "town", faction = "alliance", home = {  },
      { "Lakeshire sat on the shore of Lake Everstill, its great bridge still unfinished and its people tired. The town had the look of a place holding on.", tags = { "!foe" } },
      { "Lakeshire's bridge was guarded, and the whole town watched the hills. It did not take long for it to watch me as well.", tags = { "foe" } },
    },
    ["Light's Hope Chapel"] = { type = "town", faction = "neutral", home = {  },
      { "Light's Hope Chapel stood alone in the Eastern Plaguelands, its stones still clean and the Argent Dawn keeping watch around it. Living people of every kind gathered at its walls, with nowhere else left to go." },
    },
    ["Loch Modan"] = { type = "zone", faction = "alliance", home = {  },
      { "The blue water of Loch Modan lay still behind the Stonewrought Dam. I knew dwarves built on a grand scale, but the weight of all that water made me stop and look.", tags = { "!night" } },
      { "The loch lay black beneath the hills, with the dam a darker line against the sky. The lights of Thelsamar drew my eye along the shore.", tags = { "night" } },
      { "Across Loch Modan stood the great dam of the dwarves. I watched the guards along the water as closely as I watched the view.", tags = { "foe" } },
    },
    ["Maraudon"] = { type = "dungeon", faction = "neutral", home = {  },
      { "Maraudon was a cavern of crystal and poisoned water, home of the centaur's sacred dead and of something much older underneath. The deeper it went, the greener it grew." },
    },
    ["Marshal's Refuge"] = { type = "town", faction = "neutral", home = {  },
      { "Marshal's Refuge was a camp tucked into a cave mouth on the crater's edge, where a few hardy souls lived among the dinosaurs." },
    },
    ["Menethil Harbor"] = { type = "town", faction = "alliance", home = {  },
      { "Menethil Harbor was a fortress on the edge of the marsh, its keep half sunk into the mud and its docks busy with ships bound for Kalimdor.", tags = { "!foe" } },
      { "Menethil Harbor's keep and docks were full of Alliance soldiers coming and going by sea, and every one of them was an enemy of mine.", tags = { "foe" } },
    },
    ["Molten Core"] = { type = "dungeon", faction = "neutral", home = {  },
      { "Molten Core lay at the very bottom of Blackrock Mountain, a cavern of fire where Ragnaros himself waited. The heat was like walking into a forge." },
    },
    ["Moonbrook"] = { type = "town", faction = "neutral", home = {  },
      { "Moonbrook had been a town once. Now its houses stood burned and broken, and men in red bandanas watched the road from the ruins.", tags = { "!night" } },
      { "Moonbrook was a ruin after dark, its broken walls black against the sky. Somewhere among the burned houses the Defias were talking, and I kept to the shadows.", tags = { "night" } },
    },
    ["Moonglade"] = { type = "zone", faction = "neutral", home = {  },
      { "Moonglade was peaceful as nowhere else in the world was, a quiet lake in an endless twilight with druids walking slowly by the water. Even my thoughts went softer there." },
      { "Night in Moonglade hardly differed from day, the same soft light on the lake and the same stillness. It was the first place in a long time where I did not listen for footsteps behind me.", tags = { "night" } },
    },
    ["Morgan's Vigil"] = { type = "town", faction = "alliance", home = {  },
      { "Morgan's Vigil was a small Alliance camp at the edge of the Burning Steppes, holding on against the orcs of Blackrock.", tags = { "!foe" } },
      { "Morgan's Vigil was an Alliance camp at the edge of the Steppes, and my coming did not make their vigil any easier.", tags = { "foe" } },
    },
    ["Mulgore"] = { type = "zone", faction = "horde", home = { ["Tauren"] = true },
      { "The grass of Mulgore rolled on toward the mesas, with plainstriders running and the wind moving through it like water. The Earth Mother's land asked nothing of me but that I walk it gently.", tags = { "home", "!night" } },
      { "Night over Mulgore was wide and clear, the stars reaching down to the edge of the grass. The tents of the tribe glowed here and there, and the land felt as though it kept watch.", tags = { "home", "night" } },
      { "Mulgore's plains rolled green and gold beneath the mesas, with kodo grazing and windmills turning by the tents. It was the calmest country I had seen in a long while.", tags = { "ally" } },
      { "The plains of Mulgore were open in every direction, with nowhere to hide on them. This was the tauren's land, and I felt like a stranger walking through someone's home.", tags = { "foe" } },
    },
    ["Naxxramas"] = { type = "dungeon", faction = "neutral", home = {  },
      { "Naxxramas floated over the Plaguelands, Kel'Thuzad's necropolis, and from its cold halls the dead marched out." },
    },
    ["Nethergarde Keep"] = { type = "town", faction = "alliance", home = {  },
      { "Nethergarde Keep stood guard over the Blasted Lands, its mages watching the Dark Portal as if it might open again at any moment.", tags = { "!foe" } },
      { "Nethergarde Keep was an Alliance fortress full of mages watching the Portal. They watched me just as closely.", tags = { "foe" } },
    },
    ["Nighthaven"] = { type = "town", faction = "neutral", home = {  },
      { "Nighthaven was a village of the druids by the lake, quiet and open, where anyone who came in peace was welcome." },
    },
    ["Nijel's Point"] = { type = "town", faction = "alliance", home = {  },
      { "Nijel's Point was a small Alliance camp in the hills above Desolace, with a little green still clinging to the slopes.", tags = { "!foe" } },
      { "Nijel's Point was an Alliance camp in the hills, and a dangerous place for one of my kind.", tags = { "foe" } },
    },
    ["Onyxia's Lair"] = { type = "dungeon", faction = "neutral", home = {  },
      { "Onyxia's Lair was a cave in the marsh, littered with bones and full of whelps. Everyone fell quiet at its mouth." },
    },
    ["Orgrimmar"] = { type = "zone", faction = "horde", home = { ["Orc"] = true, ["Troll"] = true },
      { "The drums of Orgrimmar echoed off the spiked walls as I came in. At Grommash Hold I felt the weight of it: a city our people had built for themselves, with no one's chains on it.", tags = { "home" } },
      { "Smoke drifted over the red stone and iron spikes of Orgrimmar. The drums made the pride of the place something I could almost feel underfoot.", tags = { "ally" } },
      { "Under the walls of Orgrimmar, the drums rolled off the red stone. I had never felt so far from anyone who might call me a friend.", tags = { "foe" } },
    },
    ["Ragefire Chasm"] = { type = "dungeon", faction = "horde", home = { ["Orc"] = true, ["Troll"] = true },
      { "Fire ran through the rock of Ragefire Chasm, right beneath our city. That the Burning Blade could hide so close to home troubled me more than the dark.", tags = { "home" } },
      { "Magma lit Ragefire Chasm from below. I had to keep reminding myself to watch the ground rather than the fire.", tags = { "!home" } },
    },
    ["Ratchet"] = { type = "town", faction = "neutral", home = {  },
      { "Ratchet was a goblin port on the Barrens coast, all docks, cranes and haggling, with the boat to Booty Bay coming and going." },
    },
    ["Razor Hill"] = { type = "town", faction = "horde", home = { ["Orc"] = true, ["Troll"] = true },
      { "At Razor Hill I heard the forge before I saw the drilling. Beyond the barracks, Kul Tiras ships sat off the coast, and I understood why no one in the town ever quite stood at rest.", tags = { "home" } },
      { "The barracks and watchtowers of Razor Hill stood over the coast. With so many weapons in sight, it was plainly no town at peace.", tags = { "!home" } },
    },
    ["Razorfen Downs"] = { type = "dungeon", faction = "neutral", home = {  },
      { "Razorfen Downs was a mound of thorns and bones, where the quilboar had made common cause with the Scourge. The dead walked there beside the living." },
    },
    ["Razorfen Kraul"] = { type = "dungeon", faction = "neutral", home = {  },
      { "Razorfen Kraul was a maze of giant thorns, the quilboar's warrens dug deep beneath them. The brambles tore at everything that passed." },
    },
    ["Redridge Mountains"] = { type = "zone", faction = "alliance", home = {  },
      { "Red rock rose around Lake Everstill, and the bridge at Lakeshire carried more soldiers than travellers. Gnolls and Blackrock orcs had moved into the hills, and the valley had the look of a place under siege.", tags = { "!night" } },
      { "The lake at Redridge lay black under the red hills, with fires burning up on the ridges where nobody friendly had lit them. I began counting them, and stopped.", tags = { "night" } },
    },
    ["Refuge Pointe"] = { type = "town", faction = "alliance", home = {  },
      { "Refuge Pointe was a camp on a rocky height, where the last of Stromgarde's people kept their banners flying over the highlands.", tags = { "!foe" } },
      { "Refuge Pointe stood on its rock above the highlands, an Alliance camp with good eyes on every approach, mine included.", tags = { "foe" } },
    },
    ["Revantusk Village"] = { type = "town", faction = "horde", home = {  },
      { "Revantusk Village stood on the Hinterlands coast, a troll village of huts and totems where the Revantusk had taken the Horde's side.", tags = { "!foe" } },
      { "Revantusk Village was a troll village on the coast, sworn to the Horde, and no friend of mine.", tags = { "foe" } },
    },
    ["Ruins of Ahn'Qiraj"] = { type = "dungeon", faction = "neutral", home = {  },
      { "The Ruins of Ahn'Qiraj spread out in the sand beyond the scarab wall, broken towers and silithid everywhere." },
    },
    ["Scarlet Monastery"] = { type = "dungeon", faction = "neutral", home = {  },
      { "The Scarlet Monastery was beautiful and terrible, all red banners and polished floors, and the Crusaders there were sure of everything. Certainty like theirs was more frightening than anything I had met in the dark." },
    },
    ["Scholomance"] = { type = "dungeon", faction = "neutral", home = {  },
      { "Scholomance had been the Barov family's keep before it became a school for necromancers. Its halls smelled of dust and death and old books." },
    },
    ["Searing Gorge"] = { type = "zone", faction = "neutral", home = {  },
      { "The Searing Gorge was a wound in the earth, black rock and glowing slag and the stink of sulphur. The Dark Iron dwarves had worked it until nothing was left but heat.", tags = { "!night" } },
      { "In the Searing Gorge, night hardly mattered. The lava lit the cliffs from below, and the great Cauldron at its heart glowed like a second sun.", tags = { "night" } },
    },
    ["Sentinel Hill"] = { type = "town", faction = "alliance", home = { ["Human"] = true },
      { "A stone tower stood on Sentinel Hill, and around it the People's Militia had pitched their tents. Farmers who had lost everything queued for soup, and it made me angrier than I expected.", tags = { "home" } },
      { "Sentinel Hill was a tower, a hill and a camp of farmers turned soldiers. Nobody there had much, but they had decided to hold the line together.", tags = { "!home" } },
    },
    ["Shadowfang Keep"] = { type = "dungeon", faction = "neutral", home = {  },
      { "Cold stone and howling closed around me in Shadowfang Keep, high above Pyrewood. I knew of Arugal, but listened harder to the sounds behind the walls." },
    },
    ["Shadowprey Village"] = { type = "town", faction = "horde", home = {  },
      { "Shadowprey Village sat on the Desolace coast, a quiet Horde village among the reeds, far from everything.", tags = { "!foe" } },
      { "Shadowprey Village was a Horde village on the coast, and even in Desolace I was not welcome there.", tags = { "foe" } },
    },
    ["Silithus"] = { type = "zone", faction = "neutral", home = {  },
      { "Silithus was a desert of red sand and great hives, and the ground hummed with the silithid moving beneath it. The ruins of Ahn'Qiraj stood to the south, and the air felt heavy with whatever slept there.", tags = { "!night" } },
      { "Night in Silithus was full of clicking and scratching, the hives pale under the moon. I tried not to think about what was down there.", tags = { "night" } },
    },
    ["Silverpine Forest"] = { type = "zone", faction = "horde", home = {  },
      { "Rain blurred the grey lake in Silverpine, and beyond it the purple dome of Dalaran. Howls in the hills kept pulling my attention back to the trees around me.", tags = { "!night" } },
      { "Rain and howling followed me into Silverpine after dark. Behind the black wall of pines, I had no wish to find out what else was there.", tags = { "night" } },
    },
    ["Southshore"] = { type = "town", faction = "alliance", home = {  },
      { "Southshore's houses stood by the water, with a good inn and a long memory of the war. Tarren Mill was just over the hill, and nobody here forgot it.", tags = { "!foe" } },
      { "Southshore was a human town by the water, and Tarren Mill was just over the hill. Its guards knew at a glance which side I came from.", tags = { "foe" } },
    },
    ["Splintertree Post"] = { type = "town", faction = "horde", home = {  },
      { "Splintertree Post was a rough Horde camp at the edge of Ashenvale, all palisade and woodsmoke, where the axes never stopped.", tags = { "!foe" } },
      { "Splintertree Post was a Horde camp at Ashenvale's edge, the sound of axes carrying from it all day, and its guards had no welcome for me.", tags = { "foe" } },
    },
    ["Stonard"] = { type = "town", faction = "horde", home = {  },
      { "Stonard rose out of the swamp in heavy orcish stone, the one dry and certain place in the Swamp of Sorrows.", tags = { "!foe" } },
      { "Stonard was an orc fortress rising out of the swamp, and its walls were watched by people who wanted me dead.", tags = { "foe" } },
    },
    ["Stonetalon Mountains"] = { type = "zone", faction = "neutral", home = {  },
      { "The Stonetalon Mountains climbed in great grey ridges, and in places the forest had been cut back to stumps by the Venture Company's saws. The peak itself seemed to look down on all of it.", tags = { "!night" } },
      { "Stonetalon's ridges stood black against the stars, and the wind sang through the passes. Far below, the goblins' machines were still at work.", tags = { "night" } },
    },
    ["Stonetalon Peak"] = { type = "town", faction = "alliance", home = {  },
      { "Stonetalon Peak was a quiet camp high among the trees, where the druids watched over what remained of the forest.", tags = { "!foe" } },
      { "Stonetalon Peak was a night elf camp high in the mountains, quiet and watchful, and it watched me.", tags = { "foe" } },
    },
    ["Stormwind City"] = { type = "zone", faction = "alliance", home = { ["Human"] = true },
      { "The white walls of Stormwind rose over the canals, and the bells of the cathedral carried across the city. It was home, and I tried not to think about the masons who had rebuilt it and were never paid.", tags = { "home" } },
      { "Stormwind was all white stone, blue roofs and canals, with guards on every bridge. It looked like a city that had never known a war, though I knew better.", tags = { "ally" } },
      { "The white walls of Stormwind closed around me, and every guard seemed to be looking my way. I had never been so aware of my own face.", tags = { "foe" } },
    },
    ["Stranglethorn Vale"] = { type = "zone", faction = "neutral", home = {  },
      { "Stranglethorn was jungle from end to end, hot and loud with birds and full of things that wanted to eat me. Old troll ruins rose out of the green, and hunters came from all over the world to prove themselves.", tags = { "!night" } },
      { "In Stranglethorn the night was never quiet. Panthers moved through the dark, drums carried from the troll ruins, and the heat did not ease for a moment.", tags = { "night" } },
    },
    ["Stratholme"] = { type = "dungeon", faction = "neutral", home = {  },
      { "Stratholme was a city that had burned and never stopped burning, the Scourge in its streets and the Scarlet Crusade dug in among the ruins." },
    },
    ["Sun Rock Retreat"] = { type = "town", faction = "horde", home = {  },
      { "Sun Rock Retreat sheltered under the cliffs of Stonetalon, a Horde camp where the mountain stood close on every side.", tags = { "!foe" } },
      { "Sun Rock Retreat was a Horde camp tucked under the cliffs, with nowhere to go but back the way I came.", tags = { "foe" } },
    },
    ["Sunken Temple"] = { type = "dungeon", faction = "neutral", home = {  },
      { "The Sunken Temple lay half drowned in the swamp, its halls dark and dripping, where the Atal'ai still called on their blood god. The air tasted of old magic." },
    },
    ["Swamp of Sorrows"] = { type = "zone", faction = "neutral", home = {  },
      { "The Swamp of Sorrows lived up to its name: grey water, hanging moss and a silence that felt like grief. Somewhere in its depths lay the sunken temple of the Atal'ai.", tags = { "!night" } },
      { "Night in the Swamp of Sorrows was close and heavy, the air thick enough to taste. Pale lights moved over the water, and I had no intention of following them.", tags = { "night" } },
    },
    ["Tanaris"] = { type = "zone", faction = "neutral", home = {  },
      { "Tanaris was sand and heat and more sand, dunes running to the horizon under a white sky. Gadgetzan's walls were the only shade for miles.", tags = { "!night" } },
      { "The desert of Tanaris turned cold at night, and the dunes went silver. I could hear the wind moving the sand, and now and then a scorpid's claws on stone.", tags = { "night" } },
    },
    ["Tarren Mill"] = { type = "town", faction = "horde", home = {  },
      { "Tarren Mill belonged to the Forsaken now, its old houses mended after their fashion and the apothecaries busy. Southshore was just over the hill, and the town never forgot it.", tags = { "!foe" } },
      { "Tarren Mill had been a human village once; now the Forsaken held it, and the deathguards watched every road. Every one of them knew what I was.", tags = { "foe" } },
    },
    ["Teldrassil"] = { type = "zone", faction = "alliance", home = { ["NightElf"] = true },
      { "The branches of Teldrassil held the whole forest up beneath my feet. Wisps drifted over the moss of our new home, and I envied them their ease.", tags = { "home", "!night" } },
      { "Moonlight silvered the leaves of Teldrassil while owls called overhead. I listened between my footfalls, unwilling to hurry through so much quiet.", tags = { "home", "night" } },
      { "In the violet light of Teldrassil, it was hard to forget that the whole forest stood on a single tree. The thought kept drawing my eyes from the sentinels to the ground.", tags = { "ally" } },
      { "The leaves of Teldrassil softened every sound. I admired the place, and was quite sure someone had already noticed me.", tags = { "foe" } },
    },
    ["The Barrens"] = { type = "zone", faction = "horde", home = {  },
      { "Yellow grass ran on past the thorn trees of the Barrens, with zhevra shifting in the heat. Distances were harder to judge than they had looked on any map.", tags = { "!night" } },
      { "The grass of the Barrens turned silver under an enormous night sky. Somewhere far off, centaur drums carried over the grass, and I kept my eyes on the horizon.", tags = { "night" } },
    },
    ["The Crossroads"] = { type = "town", faction = "horde", home = {  },
      { "The palisade of the Crossroads stood where the roads met the grassland. After so much empty distance, people gathered in one place were a relief.", tags = { "!foe" } },
      { "At the Crossroads, the Horde's palisade sheltered its own. For me it was a reason to look carefully before I moved on.", tags = { "foe" } },
    },
    ["The Deadmines"] = { type = "dungeon", faction = "neutral", home = {  },
      { "Timber props held up the tunnels of the Deadmines, and the air tasted of dust and lamp oil. Somewhere ahead, machinery was hammering, as if the whole hill were being worked from the inside." },
      { "Mine carts stood abandoned on their rails, and the walls sweated in the lamplight. The deeper I went into the Deadmines, the louder the hammering grew." },
    },
    ["The Hinterlands"] = { type = "zone", faction = "neutral", home = {  },
      { "The Hinterlands were high and wild, forested hills where gryphons flew and the Witherbark trolls watched from their ruins. It felt like country that had never quite been tamed.", tags = { "!night" } },
      { "The Hinterlands were full of sound at night: owls, wolves, and the drums of the trolls up in the hills. It was no country for sleeping out of doors.", tags = { "night" } },
    },
    ["The Sepulcher"] = { type = "town", faction = "horde", home = { ["Scourge"] = true },
      { "Bats wheeled over the tombs of the Sepulcher, and our guards stood at the gate. Making an outpost of a burial ground seemed a fair use of what was left.", tags = { "home" } },
      { "I came to the Sepulcher through a hillside of tombs. For a moment I watched the guards warily, before I remembered who lived here.", tags = { "!home" } },
    },
    ["The Stockade"] = { type = "dungeon", faction = "neutral", home = {  },
      { "The Stockade was Stormwind's prison, built under the city, and the prisoners had taken it over. Every cell door hung open." },
    },
    ["Thelsamar"] = { type = "town", faction = "alliance", home = {  },
      { "I found the Stoutlager Inn of Thelsamar beside the loch. After the open hills, its ale and blood sausages interested me more than the distance I had come.", tags = { "!foe" } },
      { "The inn at Thelsamar looked comfortable beside the loch. On an Alliance shore, though, its windows offered more chance of being seen than of rest.", tags = { "foe" } },
    },
    ["Theramore Isle"] = { type = "town", faction = "alliance", home = {  },
      { "Theramore stood on its island off the marsh coast, stone towers and busy docks, Lady Jaina's city and the Alliance's anchor in Kalimdor.", tags = { "!foe" } },
      { "Theramore's towers rose from their island off the coast, Lady Jaina's city and the Alliance's anchor in Kalimdor. Its walls were the last place I should have been.", tags = { "foe" } },
    },
    ["Thorium Point"] = { type = "town", faction = "neutral", home = {  },
      { "Thorium Point was the Thorium Brotherhood's camp on the rim of the gorge, a few tents and a forge above all that heat." },
    },
    ["Thousand Needles"] = { type = "zone", faction = "neutral", home = {  },
      { "Thousand Needles was well named: stone pillars rose from the canyon floor by the hundred, with rope bridges strung between their tops. To the east, the Shimmering Flats shone white.", tags = { "!night" } },
      { "At night the needles of the canyon stood like a forest of black stone. The camps on the mesas showed small lights, and the drop below them was a long one.", tags = { "night" } },
    },
    ["Thunder Bluff"] = { type = "town", faction = "horde", home = { ["Tauren"] = true },
      { "Thunder Bluff stood on its mesas high above Mulgore, with tents and totems on every top and rope bridges swinging between them. The wind never stopped, and nobody seemed to mind.", tags = { "!foe" } },
      { "Thunder Bluff rose on its mesas above the plains, reached only by its great lifts. From below, there was no hope of getting in unseen.", tags = { "foe" } },
    },
    ["Tirisfal Glades"] = { type = "zone", faction = "horde", home = { ["Scourge"] = true },
      { "Under the grey sky of Tirisfal, dead trees stood where the plague had left them. I recognised something of myself in a country that had been obliged to go on.", tags = { "home", "!night" } },
      { "Crows called over the crypts of Tirisfal, toward the broken walls of Lordaeron. Night changed little here, though it left me feeling less conspicuous.", tags = { "home", "night" } },
      { "The grey fields of Tirisfal led past dead trees to the broken walls of Lordaeron. I wondered what the people here still remembered of the country.", tags = { "ally" } },
      { "Dead trees stretched across Tirisfal toward the ruins of Lordaeron. Knowing the Forsaken walked here made the stillness harder to trust.", tags = { "foe" } },
    },
    ["Uldaman"] = { type = "dungeon", faction = "neutral", home = {  },
      { "Uldaman was a vault of the titans, carved deep into the mountain, where troggs and Dark Iron dwarves fought over things neither understood. The stone itself seemed to watch." },
    },
    ["Undercity"] = { type = "zone", faction = "horde", home = { ["Scourge"] = true },
      { "Green canals ran past the bubbling Apothecarium, deep beneath the ruins of Lordaeron. Out of so much that had survived badly, we had made a city, and it was ours.", tags = { "home" } },
      { "Green sludge filled the stone canals of the Undercity, deep under Lordaeron. The smell stayed with me the whole time I was trying to find my way.", tags = { "ally" } },
      { "Below the ruins of Lordaeron, the Forsaken had made the Undercity their home. Each turn I took made the way back to daylight less certain.", tags = { "foe" } },
    },
    ["Un'Goro Crater"] = { type = "zone", faction = "neutral", home = {  },
      { "Un'Goro Crater was another world, hot and steaming, full of giant ferns and creatures that should have died out long ago. Devilsaurs walked through the jungle, and the ground shook when they did.", tags = { "!night" } },
      { "Night in Un'Goro was thick with heat and noise: insects as big as my hand, and the far-off roar of something enormous. The crater felt older than anything I knew.", tags = { "night" } },
    },
    ["Wailing Caverns"] = { type = "dungeon", faction = "neutral", home = {  },
      { "In the Wailing Caverns, the wind moaned over green water among the roots. Knowing what had become of the druids, I listened for a voice I could still reason with." },
    },
    ["Western Plaguelands"] = { type = "zone", faction = "neutral", home = {  },
      { "The Western Plaguelands had been farmland once, and the farms still stood, empty or worse. The grain was blighted, the dead walked in the fields, and Andorhal was a ruin.", tags = { "!night" } },
      { "Night in the Western Plaguelands was full of wrong sounds: shuffling feet, the creak of empty houses, the wind in dead wheat. Every shadow looked as if it might stand up.", tags = { "night" } },
    },
    ["Westfall"] = { type = "zone", faction = "alliance", home = { ["Human"] = true },
      { "Westfall's fields ran gold to the horizon, and half of them had gone to seed. Farmhouses stood empty with their doors open, and I thought of the families who had worked them before the Defias came.", tags = { "home", "!night" } },
      { "Westfall lay dark and quiet, its windmills turning over farms nobody tended any more. A light in a window was rare enough to make me wonder who still dared to keep one.", tags = { "home", "night" } },
      { "Golden fields ran down toward the sea, with windmills turning above them. It was beautiful country, and a hungry one: too many farms stood empty, and too many people on the road had nowhere else to go.", tags = { "ally" } },
      { "The fields of Westfall ran on toward the sea, with empty farms and scarecrows that were not always scarecrows. In the heart of the Alliance's farmland, I kept well away from the road.", tags = { "foe" } },
    },
    ["Wetlands"] = { type = "zone", faction = "alliance", home = {  },
      { "The Wetlands were mud, reeds and rain, and half the road lay under water. Raptors stalked the marsh, and in the east the heights of Grim Batol were not something anyone mentioned lightly.", tags = { "!night" } },
      { "At night the Wetlands came alive with croaking and splashing, and the mist lay low over the water. The road was the only thing I trusted, and in a marsh that was not saying much.", tags = { "night" } },
    },
    ["Winterspring"] = { type = "zone", faction = "neutral", home = {  },
      { "Winterspring lay deep in snow, quiet and clean, with frostsabers in the hills and steaming springs among the drifts. After so many burned and blighted places, the cold felt honest.", tags = { "!night" } },
      { "Under the stars, Winterspring's snow was blue and silent. The cold bit hard, and Everlook's lights in the distance looked very warm.", tags = { "night" } },
    },
    ["Zul'Farrak"] = { type = "dungeon", faction = "neutral", home = {  },
      { "Zul'Farrak was a troll city in the desert, its stairs and temples baking in the sun and the Sandfury watching from every wall." },
    },
    ["Zul'Gurub"] = { type = "dungeon", faction = "neutral", home = {  },
      { "Zul'Gurub was the old Gurubashi capital rising out of the jungle, its temples soaked in the blood god's worship." },
    },
  },
}
